import Extend from 'flarum/common/extenders';
import app from 'flarum/admin/app';

// Flarum provides `m` as a runtime global (not a bundled module — importing it
// would break the build here, which doesn't externalise mithril). Type it from
// @types/mithril so vnode construction is checked, instead of `any`.

const KEY = 'ernestdefoe-federation';
const t = k => app.translator.trans(`${KEY}.admin.settings.${k}`);

/** Build the live @user@host handle from the current settings + this host. */
function currentHandle() {
  const raw = app.data.settings[`${KEY}.username`] || (app.forum.attribute('title') ?? 'community');
  const slug = raw.toString().toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '');
  return `@${slug || 'community'}@${window.location.host}`;
}
export const extend = [new Extend.Admin().setting(() => ({
  setting: `${KEY}.enabled`,
  type: 'boolean',
  label: t('enabled_label'),
  help: t('enabled_help')
})).setting(() => ({
  setting: `${KEY}.username`,
  type: 'text',
  label: t('username_label'),
  help: t('username_help'),
  placeholder: 'community'
})).customSetting(() => m('.Form-group', [m('label', t('handle_label')), m('.helpText', t('handle_help')), m('pre', m('code', currentHandle()))]), 30)];